          <div class="montage-row"><button type="button" id="move-frame-left" aria-label="Передвинуть кадр влево">В ленте ←</button><button type="button" id="move-frame-right" aria-label="Передвинуть кадр вправо">В ленте →</button><button type="button" id="replace-frame">Заменить</button><button type="button" id="remove-frame">Удалить</button></div>
